values
  ('c1382a1c-8fd8-4625-b926-98fc12a68f5f', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Course Orientation, Anatomical Terminology, and Homeostasis', 'This opening unit gives students the language and logic of A' || chr(38) || 'P. It teaches how to describe the body precisely, connect structure to function, and explain why physiological systems are organized around stability and feedback.', 0),
  ('b2f88263-c454-4c97-a9e3-ea7acbfc9a95', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'c1382a1c-8fd8-4625-b926-98fc12a68f5f', 'subtopic'::public.curated_course_node_type, 'Anatomical Position and Directional Terms', 'Students learn a shared map of the body so descriptions are precise and unambiguous in lab, clinical notes, and exams.', 0),
  ('9b9c9792-93de-4310-a343-3dc2b545da07', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b2f88263-c454-4c97-a9e3-ea7acbfc9a95', 'concept'::public.curated_course_node_type, 'Anatomical position, prone and supine', null, 0),
  ('fd39a3bc-6616-45e0-97f2-a0b198ff3d18', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b2f88263-c454-4c97-a9e3-ea7acbfc9a95', 'concept'::public.curated_course_node_type, 'Superior, inferior, anterior, posterior, medial, lateral, proximal, distal', null, 1),
  ('5f2bd721-78bf-44f9-bce7-0fe4a36e45f0', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b2f88263-c454-4c97-a9e3-ea7acbfc9a95', 'concept'::public.curated_course_node_type, 'Superficial, deep, ipsilateral, contralateral', null, 2),
  ('e545bfe0-b10b-4e60-80c3-d3217893fc9c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'c1382a1c-8fd8-4625-b926-98fc12a68f5f', 'subtopic'::public.curated_course_node_type, 'Body Planes, Sections, and Cavities', 'Planes and cavities help students understand imaging, dissections, organs, and how structures are arranged in three-dimensional space.', 1),
  ('22f6f2db-233e-400e-ac09-834173a8e58c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'e545bfe0-b10b-4e60-80c3-d3217893fc9c', 'concept'::public.curated_course_node_type, 'Sagittal, frontal, transverse, and oblique planes', null, 0),
  ('abc78c08-afbb-4cbe-87f6-568286e4143a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'e545bfe0-b10b-4e60-80c3-d3217893fc9c', 'concept'::public.curated_course_node_type, 'Dorsal and ventral body cavities', null, 1),
  ('fface1ac-c795-413d-b0e0-81f23dec93f8', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'e545bfe0-b10b-4e60-80c3-d3217893fc9c', 'concept'::public.curated_course_node_type, 'Thoracic, abdominal, pelvic, and abdominopelvic regions', null, 2),
  ('4599a170-b061-48bf-8468-d24c92c65ca6', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'c1382a1c-8fd8-4625-b926-98fc12a68f5f', 'subtopic'::public.curated_course_node_type, 'Levels of Structural Organization', 'A' || chr(38) || 'P makes more sense when students can move from atoms and cells to tissues, organs, systems, and the whole organism.', 2),
  ('e0112c22-4a7f-4dc6-8861-19a9dae87ac8', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '4599a170-b061-48bf-8468-d24c92c65ca6', 'concept'::public.curated_course_node_type, 'Chemical, cellular, tissue, organ, system, organismal levels', null, 0),
  ('68636552-513f-43e4-8809-39f0eaf2bbc2', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '4599a170-b061-48bf-8468-d24c92c65ca6', 'concept'::public.curated_course_node_type, 'Structure-function relationships', null, 1),
  ('7bec31a1-4356-4168-9d36-9c58a943d16b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '4599a170-b061-48bf-8468-d24c92c65ca6', 'concept'::public.curated_course_node_type, 'System integration across levels', null, 2),
  ('07668743-9304-4f0d-9243-d91a3828184f', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'c1382a1c-8fd8-4625-b926-98fc12a68f5f', 'subtopic'::public.curated_course_node_type, 'Homeostasis and Feedback Control', 'Homeostasis explains why body systems constantly regulate variables such as temperature, calcium, glucose, and blood pressure.', 3),
  ('a3489107-faa4-4007-b43e-f5a777ded153', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '07668743-9304-4f0d-9243-d91a3828184f', 'concept'::public.curated_course_node_type, 'Controlled variables and set points', null, 0),
  ('e1f3e8c6-722a-4f5f-8a7c-534529f4afc1', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '07668743-9304-4f0d-9243-d91a3828184f', 'concept'::public.curated_course_node_type, 'Receptors, control centers, and effectors', null, 1),
  ('44886188-5a1c-47cd-a296-717847533af5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '07668743-9304-4f0d-9243-d91a3828184f', 'concept'::public.curated_course_node_type, 'Negative feedback, positive feedback, and homeostatic imbalance', null, 2),
  ('03485bd8-b2de-412c-93e2-65e14fff767a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Chemistry for Anatomy and Physiology', 'This unit reviews the chemistry needed to understand cells, tissues, muscle contraction, nerve impulses, and hormone action. The goal is not chemistry for its own sake, but chemistry as the operating system of the body.', 1),
  ('535f1fd3-f472-4ce0-86dd-c1466379bf23', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '03485bd8-b2de-412c-93e2-65e14fff767a', 'subtopic'::public.curated_course_node_type, 'Atoms, Ions, and Chemical Bonds', 'Students learn why ions, charges, and bonds matter for membranes, enzymes, muscle contraction, and neural signaling.', 0),
  ('0b514b8a-5b21-40cc-84f8-e16b3051970e', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '535f1fd3-f472-4ce0-86dd-c1466379bf23', 'concept'::public.curated_course_node_type, 'Atomic structure and isotopes', null, 0),
  ('69b5bcb5-d3fc-4fb3-bfe8-ecc9d21057d4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '535f1fd3-f472-4ce0-86dd-c1466379bf23', 'concept'::public.curated_course_node_type, 'Ionic, covalent, and hydrogen bonds', null, 1),
  ('e4653975-4295-40e1-b521-d27de8ec8392', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '535f1fd3-f472-4ce0-86dd-c1466379bf23', 'concept'::public.curated_course_node_type, 'Electrolytes and biologically important ions', null, 2),
  ('9e260c81-980f-4221-a92c-4335ef553642', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '03485bd8-b2de-412c-93e2-65e14fff767a', 'subtopic'::public.curated_course_node_type, 'Water, pH, and Buffers', 'Water and pH shape nearly every physiological process, from protein structure to blood chemistry and cellular reactions.', 1),
  ('8a310a42-efad-4480-bcbb-a7d55cf4bfe0', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '9e260c81-980f-4221-a92c-4335ef553642', 'concept'::public.curated_course_node_type, 'Polarity, cohesion, adhesion, and solvent properties', null, 0),
  ('bb37dd5f-90e3-4bc8-af71-cdb427b01fa5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '9e260c81-980f-4221-a92c-4335ef553642', 'concept'::public.curated_course_node_type, 'Acids, bases, pH scale, and buffers', null, 1),
  ('2fdcbeaf-538d-4d7a-aa8f-56a5ed9f8848', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '9e260c81-980f-4221-a92c-4335ef553642', 'concept'::public.curated_course_node_type, 'Physiological consequences of pH shifts', null, 2),
  ('60ef84d2-cd3d-46a0-b6aa-fbe7bc156675', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '03485bd8-b2de-412c-93e2-65e14fff767a', 'subtopic'::public.curated_course_node_type, 'Biomolecules', 'Macromolecules are the materials and tools of cells: fuel, membranes, enzymes, receptors, and structural components.', 2),
  ('a0805c52-06b6-4500-9823-319d8f328d73', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '60ef84d2-cd3d-46a0-b6aa-fbe7bc156675', 'concept'::public.curated_course_node_type, 'Carbohydrates and glycogen', null, 0),
  ('a92eb051-1e79-4943-9604-33f3f80ede91', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '60ef84d2-cd3d-46a0-b6aa-fbe7bc156675', 'concept'::public.curated_course_node_type, 'Lipids, phospholipids, steroids, and triglycerides', null, 1),
  ('50bdf2a7-0a0d-468b-a921-77814340204b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '60ef84d2-cd3d-46a0-b6aa-fbe7bc156675', 'concept'::public.curated_course_node_type, 'Proteins, enzymes, nucleic acids, ATP', null, 2),
  ('b6e36d53-303b-43cb-a3d6-837c0bc64d93', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '03485bd8-b2de-412c-93e2-65e14fff767a', 'subtopic'::public.curated_course_node_type, 'Chemical Reactions and Energy', 'Students see how the body builds, breaks down, and transfers energy in ways that support tissue function.', 3),
  ('97a4291b-32a9-456d-bcf1-0aae1bb18a76', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b6e36d53-303b-43cb-a3d6-837c0bc64d93', 'concept'::public.curated_course_node_type, 'Synthesis, decomposition, and exchange reactions', null, 0),
  ('b2569386-bc88-4537-9d03-0ea4a393442c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b6e36d53-303b-43cb-a3d6-837c0bc64d93', 'concept'::public.curated_course_node_type, 'Activation energy and enzymes', null, 1),
  ('4ad59269-09e7-424a-8fa5-642736d6f453', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b6e36d53-303b-43cb-a3d6-837c0bc64d93', 'concept'::public.curated_course_node_type, 'ATP as cellular energy currency', null, 2),
  ('3a830f90-2291-4c19-8e4d-8296f060b81b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Cells, Membranes, and Cellular Metabolism', 'Cells are the smallest living units students will use to explain tissues and organs. This unit builds fluency with organelles, membranes, transport, protein synthesis, cell division, and energy production.', 2),
  ('8b512751-9c7b-4e93-ab59-193c2ad7136d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '3a830f90-2291-4c19-8e4d-8296f060b81b', 'subtopic'::public.curated_course_node_type, 'Cell Structure and Organelles', 'Students learn what cell parts do and how specialized cells reflect the work they perform.', 0),
  ('bbb11a8f-3a9f-40b9-af20-5078f785c994', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8b512751-9c7b-4e93-ab59-193c2ad7136d', 'concept'::public.curated_course_node_type, 'Plasma membrane, cytoplasm, nucleus', null, 0),
  ('6deb5fb4-e133-4e25-b63a-49d33933a2fe', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8b512751-9c7b-4e93-ab59-193c2ad7136d', 'concept'::public.curated_course_node_type, 'Ribosomes, rough and smooth ER, Golgi apparatus', null, 1),
  ('c82534b6-a4cd-443f-b5f0-88c461babbae', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8b512751-9c7b-4e93-ab59-193c2ad7136d', 'concept'::public.curated_course_node_type, 'Mitochondria, lysosomes, peroxisomes, cytoskeleton', null, 2),
  ('41aad98f-e3db-483a-84dd-8fea913b0f83', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '3a830f90-2291-4c19-8e4d-8296f060b81b', 'subtopic'::public.curated_course_node_type, 'Membrane Transport', 'Transport explains how cells maintain internal conditions, communicate, and respond to changing environments.', 1),
  ('42ae216a-f6d4-436f-8ad2-0bd9ceecc11b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '41aad98f-e3db-483a-84dd-8fea913b0f83', 'concept'::public.curated_course_node_type, 'Diffusion, osmosis, facilitated diffusion', null, 0),
  ('d648f48d-597b-4dbc-b890-2e17071e57f1', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '41aad98f-e3db-483a-84dd-8fea913b0f83', 'concept'::public.curated_course_node_type, 'Primary and secondary active transport', null, 1),
  ('d3767663-4c13-4b37-97f3-4cdc4cad13eb', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '41aad98f-e3db-483a-84dd-8fea913b0f83', 'concept'::public.curated_course_node_type, 'Endocytosis, exocytosis, tonicity', null, 2),
  ('8cee795c-1532-4599-9fe9-1d18a1c26da3', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '3a830f90-2291-4c19-8e4d-8296f060b81b', 'subtopic'::public.curated_course_node_type, 'Protein Synthesis and Gene Expression', 'This subtopic connects DNA instructions to the proteins that create cell structure, enzymes, receptors, and tissue function.', 2),
  ('c06865ee-e08b-4a67-bb0a-622d6ff6f9ea', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8cee795c-1532-4599-9fe9-1d18a1c26da3', 'concept'::public.curated_course_node_type, 'DNA, RNA, transcription, translation', null, 0),
  ('d124ebc3-99f4-428a-aed4-6f14c5d073a5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8cee795c-1532-4599-9fe9-1d18a1c26da3', 'concept'::public.curated_course_node_type, 'Codons, amino acids, and polypeptides', null, 1),
  ('0d5544e5-d897-4e5c-8daa-a598aba5ef3f', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8cee795c-1532-4599-9fe9-1d18a1c26da3', 'concept'::public.curated_course_node_type, 'Basic regulation and clinical relevance of protein errors', null, 2),
  ('18a15368-4092-41d0-b24c-b55404f5f3cb', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '3a830f90-2291-4c19-8e4d-8296f060b81b', 'subtopic'::public.curated_course_node_type, 'Cellular Respiration and Cell Division', 'Students learn how cells make ATP and renew tissues through controlled growth and division.', 3),
  ('dffe706f-e47c-4662-9c95-6dfe72c054de', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '18a15368-4092-41d0-b24c-b55404f5f3cb', 'concept'::public.curated_course_node_type, 'Glycolysis, Krebs cycle, electron transport overview', null, 0),
  ('b9b0a08f-707e-463a-ae1d-91844479711c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '18a15368-4092-41d0-b24c-b55404f5f3cb', 'concept'::public.curated_course_node_type, 'Aerobic versus anaerobic ATP production', null, 1),
  ('ce8f68db-8497-4940-8178-20c76e9e38b4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '18a15368-4092-41d0-b24c-b55404f5f3cb', 'concept'::public.curated_course_node_type, 'Cell cycle, mitosis, and basic cancer vocabulary', null, 2),
  ('6fc1d77d-3e46-487d-8320-cc0f9f3b6d17', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Tissues and Histology', 'This unit teaches students to recognize the four basic tissue types and explain how microscopic organization supports organ function. It also builds lab skills for slide identification.', 3),
  ('b098afcf-57b4-4879-96d1-b1ef16556e05', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6fc1d77d-3e46-487d-8320-cc0f9f3b6d17', 'subtopic'::public.curated_course_node_type, 'Epithelial Tissue', 'Epithelia cover surfaces, line cavities, and form glands, so students learn how shape and layering predict function.', 0),
  ('6df12fe4-9cc5-4285-8c7e-01911897808a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b098afcf-57b4-4879-96d1-b1ef16556e05', 'concept'::public.curated_course_node_type, 'Simple, stratified, pseudostratified, and transitional epithelia', null, 0),
  ('2e941b3a-06e8-4c6d-be26-464b79ea1533', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b098afcf-57b4-4879-96d1-b1ef16556e05', 'concept'::public.curated_course_node_type, 'Squamous, cuboidal, and columnar cells', null, 1),
  ('93b020f2-f2af-4633-9871-560030eced28', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b098afcf-57b4-4879-96d1-b1ef16556e05', 'concept'::public.curated_course_node_type, 'Absorption, secretion, filtration, protection', null, 2),
  ('76a905a1-6eef-43fc-b99d-115e9c187797', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6fc1d77d-3e46-487d-8320-cc0f9f3b6d17', 'subtopic'::public.curated_course_node_type, 'Connective Tissue', 'Connective tissues support, bind, protect, store energy, and transport substances throughout the body.', 1),
  ('6fdfa9ea-32c8-4482-99bd-1bf9e46fff63', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '76a905a1-6eef-43fc-b99d-115e9c187797', 'concept'::public.curated_course_node_type, 'Cells, fibers, and ground substance', null, 0),
  ('13af0a9f-e21d-4615-b59a-611b9e623df6', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '76a905a1-6eef-43fc-b99d-115e9c187797', 'concept'::public.curated_course_node_type, 'Loose and dense connective tissue', null, 1),
  ('b115bbc1-7e3b-4fa0-a9d4-e5605780bdcf', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '76a905a1-6eef-43fc-b99d-115e9c187797', 'concept'::public.curated_course_node_type, 'Cartilage, bone, blood, and adipose tissue', null, 2),
  ('b4feec67-efbb-4d9f-8a58-f7a6d28822f5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6fc1d77d-3e46-487d-8320-cc0f9f3b6d17', 'subtopic'::public.curated_course_node_type, 'Muscle and Nervous Tissue', 'Students preview excitable tissues before studying the muscular and nervous systems in depth.', 2),
  ('fe2399a6-64e6-4252-8c66-535dea45b02d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b4feec67-efbb-4d9f-8a58-f7a6d28822f5', 'concept'::public.curated_course_node_type, 'Skeletal, cardiac, and smooth muscle', null, 0),
  ('f719fccc-a56d-4765-81e8-2fc596fd4819', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b4feec67-efbb-4d9f-8a58-f7a6d28822f5', 'concept'::public.curated_course_node_type, 'Neurons and neuroglia', null, 1),
  ('7e4ff6d7-3908-4651-9959-144381cdfe94', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b4feec67-efbb-4d9f-8a58-f7a6d28822f5', 'concept'::public.curated_course_node_type, 'Excitability, conductivity, contractility', null, 2),
  ('a01a2a70-7b3b-4dd6-918a-d7dfd1c9b1cf', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6fc1d77d-3e46-487d-8320-cc0f9f3b6d17', 'subtopic'::public.curated_course_node_type, 'Tissue Repair and Membranes', 'Repair and membranes connect histology to inflammation, wounds, organ lining, and clinical observation.', 3),
  ('44a52bd8-16e5-42fd-bd43-ecb625be10ae', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a01a2a70-7b3b-4dd6-918a-d7dfd1c9b1cf', 'concept'::public.curated_course_node_type, 'Inflammation and regeneration versus fibrosis', null, 0),
  ('fc5423b7-a7d7-4ac8-b941-a60b805c7c69', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a01a2a70-7b3b-4dd6-918a-d7dfd1c9b1cf', 'concept'::public.curated_course_node_type, 'Mucous, serous, cutaneous, and synovial membranes', null, 1),
  ('5ffb8fb2-c788-412b-a5f6-cc99f2c2d527', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a01a2a70-7b3b-4dd6-918a-d7dfd1c9b1cf', 'concept'::public.curated_course_node_type, 'Aging effects on tissue healing', null, 2),
  ('31b5006b-b517-4b74-ae50-69452b0efb6d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Integumentary System', 'The integumentary system is an accessible system for connecting anatomy, histology, physiology, protection, thermoregulation, sensation, and clinical assessment.', 4),
  ('43f8450e-c2fc-4009-8d93-37565cf597a4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '31b5006b-b517-4b74-ae50-69452b0efb6d', 'subtopic'::public.curated_course_node_type, 'Skin Layers and Accessory Structures', 'Students learn the organization of epidermis, dermis, glands, hair, and nails as a structure-function system.', 0),
  ('c210606d-41f2-4d4f-8164-b53e1af2a7de', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '43f8450e-c2fc-4009-8d93-37565cf597a4', 'concept'::public.curated_course_node_type, 'Epidermal strata and keratinization', null, 0),
  ('4bc16760-230b-474a-8294-ae46db071100', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '43f8450e-c2fc-4009-8d93-37565cf597a4', 'concept'::public.curated_course_node_type, 'Papillary and reticular dermis', null, 1),
  ('96cb633b-d768-4533-90b8-3c846046cb08', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '43f8450e-c2fc-4009-8d93-37565cf597a4', 'concept'::public.curated_course_node_type, 'Hair follicles, nails, sebaceous glands, sweat glands', null, 2),
  ('752f4687-0fec-4fb4-a088-9e615e084a6b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '31b5006b-b517-4b74-ae50-69452b0efb6d', 'subtopic'::public.curated_course_node_type, 'Functions of Skin', 'Skin is more than a covering: it participates in protection, temperature regulation, sensation, immunity, and vitamin D production.', 1),
  ('e1ecd681-d7f7-4c3c-a4bf-81f19ea21416', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '752f4687-0fec-4fb4-a088-9e615e084a6b', 'concept'::public.curated_course_node_type, 'Barrier and immune defense', null, 0),
  ('74df1468-d6f4-4902-a8ea-ca0d62e97046', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '752f4687-0fec-4fb4-a088-9e615e084a6b', 'concept'::public.curated_course_node_type, 'Thermoregulation through vessels and sweat', null, 1),
  ('110fd5f7-1444-48f7-8a37-275757045c5c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '752f4687-0fec-4fb4-a088-9e615e084a6b', 'concept'::public.curated_course_node_type, 'Cutaneous sensation and vitamin D synthesis', null, 2),
  ('df11615d-d91a-4d8c-83c4-bdd569aee9b3', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '31b5006b-b517-4b74-ae50-69452b0efb6d', 'subtopic'::public.curated_course_node_type, 'Pigmentation, Aging, and Repair', 'These topics help students interpret visible skin changes and link them to physiology and tissue repair.', 2),
  ('c86406fe-b318-4a85-a770-c695ff5ec127', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'df11615d-d91a-4d8c-83c4-bdd569aee9b3', 'concept'::public.curated_course_node_type, 'Melanin, carotene, hemoglobin, and skin color', null, 0),
  ('d1a535b9-97d7-4227-95cf-9e5e8576c9bd', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'df11615d-d91a-4d8c-83c4-bdd569aee9b3', 'concept'::public.curated_course_node_type, 'Wound healing phases', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('64f2ae41-cdf3-4d09-9c88-4caffcabb123', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'df11615d-d91a-4d8c-83c4-bdd569aee9b3', 'concept'::public.curated_course_node_type, 'Burns, pressure injuries, and aging changes', null, 2),
  ('56709fae-76fc-4a84-87a8-7d1da46c653c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Bone Tissue and Skeletal Physiology', 'This unit explains bone as a living tissue, not just a rigid frame. Students learn how bone grows, remodels, stores minerals, and responds to mechanical and hormonal signals.', 5),
  ('66bf37be-3966-480c-a06a-697f9a7f61c4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '56709fae-76fc-4a84-87a8-7d1da46c653c', 'subtopic'::public.curated_course_node_type, 'Bone Cells and Matrix', 'Students learn how osteoblasts, osteocytes, and osteoclasts build and remodel mineralized connective tissue.', 0),
  ('10d3647e-fdd9-44c1-aca3-6c595e553da3', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '66bf37be-3966-480c-a06a-697f9a7f61c4', 'concept'::public.curated_course_node_type, 'Organic and inorganic matrix', null, 0),
  ('7ce175ad-9ea0-48d0-a456-939f45e8c26d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '66bf37be-3966-480c-a06a-697f9a7f61c4', 'concept'::public.curated_course_node_type, 'Compact and spongy bone', null, 1),
  ('c0f32378-7f2e-4148-a3fc-0971766605dc', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '66bf37be-3966-480c-a06a-697f9a7f61c4', 'concept'::public.curated_course_node_type, 'Osteogenic cells, osteoblasts, osteocytes, osteoclasts', null, 2),
  ('8f80e949-f0ca-4107-a5dc-d391ecb5545b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '56709fae-76fc-4a84-87a8-7d1da46c653c', 'subtopic'::public.curated_course_node_type, 'Bone Formation and Growth', 'Growth explains how the skeleton develops and why age, hormones, and nutrition affect bone structure.', 1),
  ('2ef437f7-544e-4e11-ba87-f8dafd578bfb', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8f80e949-f0ca-4107-a5dc-d391ecb5545b', 'concept'::public.curated_course_node_type, 'Intramembranous and endochondral ossification', null, 0),
  ('68e88554-86f4-40d4-bf4e-d75ea7637767', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8f80e949-f0ca-4107-a5dc-d391ecb5545b', 'concept'::public.curated_course_node_type, 'Epiphyseal plates and longitudinal growth', null, 1),
  ('22fa0d22-ebc8-412b-bd74-d17bcca278e5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '8f80e949-f0ca-4107-a5dc-d391ecb5545b', 'concept'::public.curated_course_node_type, 'Appositional growth and remodeling', null, 2),
  ('6974f8ea-c72a-496e-9791-5c37c1d40818', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '56709fae-76fc-4a84-87a8-7d1da46c653c', 'subtopic'::public.curated_course_node_type, 'Calcium Homeostasis and Bone Repair', 'Students connect skeletal physiology to blood calcium, fracture healing, and common health concerns.', 2),
  ('269ab14c-46c9-4758-ae2a-5546445aa157', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6974f8ea-c72a-496e-9791-5c37c1d40818', 'concept'::public.curated_course_node_type, 'Parathyroid hormone, calcitonin, and vitamin D', null, 0),
  ('c40fab8c-31c7-44fb-8c44-0edbc253c0bd', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6974f8ea-c72a-496e-9791-5c37c1d40818', 'concept'::public.curated_course_node_type, 'Bone remodeling and Wolff''s law', null, 1),
  ('6f187db8-5da6-454f-a5ff-00397bbf27af', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '6974f8ea-c72a-496e-9791-5c37c1d40818', 'concept'::public.curated_course_node_type, 'Fracture repair and osteoporosis basics', null, 2),
  ('2dd2444d-4d02-4d93-8b03-8d5015efee57', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Axial and Appendicular Skeleton', 'This unit focuses on identifying major bones and landmarks while linking skeletal structures to protection, posture, movement, and muscle attachment.', 6),
  ('86862623-2e42-42d6-9fc3-adfe4ce64420', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '2dd2444d-4d02-4d93-8b03-8d5015efee57', 'subtopic'::public.curated_course_node_type, 'Axial Skeleton', 'The axial skeleton protects the brain, spinal cord, and thoracic organs while establishing the body axis.', 0),
  ('7029b4f9-a1d6-423e-803b-ea0336dc1bbf', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '86862623-2e42-42d6-9fc3-adfe4ce64420', 'concept'::public.curated_course_node_type, 'Skull, cranial bones, facial bones, and sinuses', null, 0),
  ('b39867f4-4c06-4ad8-bed8-ef9cf12f05a1', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '86862623-2e42-42d6-9fc3-adfe4ce64420', 'concept'::public.curated_course_node_type, 'Vertebral column and vertebral regions', null, 1),
  ('8f209ace-7cc0-4948-a340-a0d31f2290c5', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '86862623-2e42-42d6-9fc3-adfe4ce64420', 'concept'::public.curated_course_node_type, 'Ribs, sternum, thoracic cage', null, 2),
  ('a6d0487f-2d42-44f9-a5c7-af5e8a9de130', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '2dd2444d-4d02-4d93-8b03-8d5015efee57', 'subtopic'::public.curated_course_node_type, 'Appendicular Skeleton', 'The appendicular skeleton supports limb movement and provides major attachment sites for muscles.', 1),
  ('0bcf0fad-8a52-448f-9f27-cb718c7df386', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a6d0487f-2d42-44f9-a5c7-af5e8a9de130', 'concept'::public.curated_course_node_type, 'Pectoral girdle and upper limb bones', null, 0),
  ('281932be-a5d4-4b1e-a246-07d1f61ce370', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a6d0487f-2d42-44f9-a5c7-af5e8a9de130', 'concept'::public.curated_course_node_type, 'Pelvic girdle and lower limb bones', null, 1),
  ('d6ed7aa2-2b73-494e-9f98-336183372cf0', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a6d0487f-2d42-44f9-a5c7-af5e8a9de130', 'concept'::public.curated_course_node_type, 'Hand, wrist, foot, and ankle bones', null, 2),
  ('366dbaab-b823-4bf0-9831-c73524e1f4ef', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '2dd2444d-4d02-4d93-8b03-8d5015efee57', 'subtopic'::public.curated_course_node_type, 'Bone Landmarks and Lab Identification', 'Landmarks matter because nerves, vessels, ligaments, and muscles relate to specific surfaces and projections.', 2),
  ('ddd6bbfd-4a25-456b-b7e5-f8127d5056e1', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '366dbaab-b823-4bf0-9831-c73524e1f4ef', 'concept'::public.curated_course_node_type, 'Processes, tubercles, tuberosities, condyles, foramina', null, 0),
  ('07c0bd7d-9305-40ad-bb68-7686b099b645', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '366dbaab-b823-4bf0-9831-c73524e1f4ef', 'concept'::public.curated_course_node_type, 'Palpable landmarks and surface anatomy', null, 1),
  ('144b0aed-e10c-4ea0-bd35-4f21decf8d8a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '366dbaab-b823-4bf0-9831-c73524e1f4ef', 'concept'::public.curated_course_node_type, 'Left-right orientation and articulating surfaces', null, 2),
  ('d799bb03-77fd-453d-a86f-3b2cbcc1000c', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Joints and Articulations', 'Joints explain how the skeleton permits movement while preserving stability. This unit prepares students to describe mobility, injury risk, and movement vocabulary.', 7),
  ('1b9a487a-3a24-464b-8b25-5eea908d8da4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'd799bb03-77fd-453d-a86f-3b2cbcc1000c', 'subtopic'::public.curated_course_node_type, 'Joint Classification', 'Students classify joints by structure and function to predict mobility and stability.', 0),
  ('1be7bea7-2ebe-470e-bf6b-3ae72f136108', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '1b9a487a-3a24-464b-8b25-5eea908d8da4', 'concept'::public.curated_course_node_type, 'Fibrous, cartilaginous, and synovial joints', null, 0),
  ('57592982-2ead-4099-a4f1-0ac171e41648', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '1b9a487a-3a24-464b-8b25-5eea908d8da4', 'concept'::public.curated_course_node_type, 'Synarthrosis, amphiarthrosis, diarthrosis', null, 1),
  ('74d15c2c-bf8d-48b5-9699-0dd4a244d844', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '1b9a487a-3a24-464b-8b25-5eea908d8da4', 'concept'::public.curated_course_node_type, 'Examples across skull, spine, limbs, and pelvis', null, 2),
  ('f6fe3945-937c-4805-a20c-7d38b28eef84', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'd799bb03-77fd-453d-a86f-3b2cbcc1000c', 'subtopic'::public.curated_course_node_type, 'Synovial Joint Anatomy', 'Synovial joints dominate limb movement, so students learn the components that reduce friction and guide motion.', 1),
  ('b3b87176-120f-4a31-a5fb-49994f3a040e', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'f6fe3945-937c-4805-a20c-7d38b28eef84', 'concept'::public.curated_course_node_type, 'Articular cartilage, synovial cavity, synovial membrane', null, 0),
  ('324ed8cd-faf5-4c35-91cb-5f46cc2ba1ca', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'f6fe3945-937c-4805-a20c-7d38b28eef84', 'concept'::public.curated_course_node_type, 'Capsules, ligaments, bursae, tendon sheaths', null, 1),
  ('652befe6-db1d-4589-83da-73960d6111c4', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'f6fe3945-937c-4805-a20c-7d38b28eef84', 'concept'::public.curated_course_node_type, 'Menisci, labra, and joint reinforcement', null, 2),
  ('b946141f-c80c-48af-919b-64df0b720fa0', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'd799bb03-77fd-453d-a86f-3b2cbcc1000c', 'subtopic'::public.curated_course_node_type, 'Movement Terminology and Selected Joints', 'Movement terms let students describe what muscles do and how joints function in daily activity.', 2),
  ('224095cb-6215-4fb6-9507-98d32d35a877', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b946141f-c80c-48af-919b-64df0b720fa0', 'concept'::public.curated_course_node_type, 'Flexion, extension, abduction, adduction, rotation', null, 0),
  ('4031ba15-bd1c-4a3b-aa44-0fdad8c3db63', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b946141f-c80c-48af-919b-64df0b720fa0', 'concept'::public.curated_course_node_type, 'Shoulder, elbow, hip, knee, ankle, and intervertebral joints', null, 1),
  ('b31e88a4-6c79-47bf-8fbb-ccf4c50c4e9d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'b946141f-c80c-48af-919b-64df0b720fa0', 'concept'::public.curated_course_node_type, 'Sprains, dislocations, arthritis, and joint health', null, 2),
  ('5e8a80f2-3ee5-46a7-8b1b-7a79d2c71fda', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Skeletal Muscle Tissue and Muscle Physiology', 'This unit explains how skeletal muscle contracts, uses energy, and produces force. It turns memorized muscle names into functional physiology.', 8),
  ('ebb08699-0f8a-47bc-a997-512933761099', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '5e8a80f2-3ee5-46a7-8b1b-7a79d2c71fda', 'subtopic'::public.curated_course_node_type, 'Muscle Fiber Structure', 'Students learn the microscopic organization that makes contraction possible.', 0),
  ('875a990f-f4fa-4158-975e-cbfc2ccc8a80', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ebb08699-0f8a-47bc-a997-512933761099', 'concept'::public.curated_course_node_type, 'Endomysium, perimysium, epimysium', null, 0),
  ('f418ac36-6135-41aa-a51c-fc5a24dca56a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ebb08699-0f8a-47bc-a997-512933761099', 'concept'::public.curated_course_node_type, 'Myofibrils, sarcomeres, actin, myosin', null, 1),
  ('d350877a-1a80-40bc-a2ee-992e665ac42f', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ebb08699-0f8a-47bc-a997-512933761099', 'concept'::public.curated_course_node_type, 'Sarcoplasmic reticulum and T-tubules', null, 2),
  ('a7e27fac-7ef4-4377-8aa2-0ed695b63f2a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '5e8a80f2-3ee5-46a7-8b1b-7a79d2c71fda', 'subtopic'::public.curated_course_node_type, 'Neuromuscular Junction and Excitation-Contraction Coupling', 'This subtopic shows how a nerve signal becomes muscle force.', 1),
  ('604392d5-de50-4506-9b41-ee929103f31a', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a7e27fac-7ef4-4377-8aa2-0ed695b63f2a', 'concept'::public.curated_course_node_type, 'Motor neurons and motor units', null, 0),
  ('e36804e3-86f1-44c5-8c99-1c5a0d9a12f9', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a7e27fac-7ef4-4377-8aa2-0ed695b63f2a', 'concept'::public.curated_course_node_type, 'Acetylcholine and motor end plate', null, 1),
  ('e5e202f4-bc0e-4c93-a2b5-7a35b98439f7', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'a7e27fac-7ef4-4377-8aa2-0ed695b63f2a', 'concept'::public.curated_course_node_type, 'Calcium release, cross-bridge cycling, relaxation', null, 2),
  ('dc27bf15-057d-4b5d-aa6a-8ba06f261b03', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '5e8a80f2-3ee5-46a7-8b1b-7a79d2c71fda', 'subtopic'::public.curated_course_node_type, 'Muscle Metabolism and Fatigue', 'Students connect ATP demand, oxygen use, and fiber type to performance and fatigue.', 2),
  ('78f57d1e-717c-49b9-b931-060010ae835e', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'dc27bf15-057d-4b5d-aa6a-8ba06f261b03', 'concept'::public.curated_course_node_type, 'Creatine phosphate, anaerobic glycolysis, aerobic respiration', null, 0),
  ('a7651136-518d-45e3-9ba3-184f906e449b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'dc27bf15-057d-4b5d-aa6a-8ba06f261b03', 'concept'::public.curated_course_node_type, 'Slow oxidative, fast oxidative-glycolytic, fast glycolytic fibers', null, 1),
  ('79fd87ec-71c1-45ae-88f2-7f0ca298348b', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'dc27bf15-057d-4b5d-aa6a-8ba06f261b03', 'concept'::public.curated_course_node_type, 'Fatigue, oxygen debt, and conditioning', null, 2),
  ('ed6fb168-e3b9-4398-ab09-28976a6f5166', '69ad6600-bbc9-445a-b712-48bfc20e7dff', '5e8a80f2-3ee5-46a7-8b1b-7a79d2c71fda', 'subtopic'::public.curated_course_node_type, 'Whole-Muscle Mechanics', 'Students learn how muscles vary force and produce graded movement.', 3),
  ('3242ac0f-16fe-42ed-8bdb-e89a972cc07d', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ed6fb168-e3b9-4398-ab09-28976a6f5166', 'concept'::public.curated_course_node_type, 'Twitches, summation, tetanus', null, 0),
  ('18234820-2a21-4c13-bd06-aebacbaed057', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ed6fb168-e3b9-4398-ab09-28976a6f5166', 'concept'::public.curated_course_node_type, 'Isotonic and isometric contractions', null, 1),
  ('44d3a88f-e6b1-4c94-9e0a-dcfb9d6481ab', '69ad6600-bbc9-445a-b712-48bfc20e7dff', 'ed6fb168-e3b9-4398-ab09-28976a6f5166', 'concept'::public.curated_course_node_type, 'Length-tension relationship and recruitment', null, 2),
  ('c1bdb501-90e8-41f1-9cf9-70b3ede2edca', '69ad6600-bbc9-445a-b712-48bfc20e7dff', null, 'topic'::public.curated_course_node_type, 'Muscular System Anatomy and Movement', 'This unit builds practical muscle identification and movement analysis. Students learn major muscles by region, action, innervation themes, and functional groupings.', 9),
